def slug(s):
    import unicodedata
    s=unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode().lower()
    return re.sub(r'[^a-z0-9]+','-',s).strip('-')

def genius_url(track):
    return 'https://genius.com/Cul-pointu-'+slug(track)+'-lyrics'

def header(active=''):
    return f'''<header><a class="brand" href="index.html">LA CRÉATURE<br><span>DU MARAIS</span></a><nav><a href="index.html#bio">Biographie</a><a class="{ 'active' if active=='discographie' else ''}" href="discographie.html">Discographie</a><a href="index.html#clips">Clips</a><a href="index.html#archives">Archives</a><a href="index.html#presse">Presse</a></nav></header>'''

def footer():
    return '<footer>LA CRÉATURE DU MARAIS · TANCRÈDE CHARON · ROUEN · CUL-POINTU · PUANTEUR PUTRIDE PRODUCTIONS</footer>'

cover_style='''<div class="cover-fallback"><span>CUL-POINTU</span><strong>{title}</strong><small>{year}</small></div>'''

def cover_html(a, linked=True):
    inner = f'<img src="{html.escape(a["cover"])}" alt="Pochette de {html.escape(a["title"])}">' if a['cover'] else cover_style.format(title=html.escape(a['title']),year=a['year'])
    return f'<a class="cover" href="albums/{a["slug"]}.html">{inner}</a>' if linked else f'<div class="cover">{inner}</div>'

